import { entryInputToText } from "@/foundation/rustledger/entry-build";
import type { LedgerEntryInput } from "@/foundation/ledger-api-types/ledger-entry-input";
import golden from "./entry-build.golden.json";

/**
 * GOLDEN parity test. `entry-build.golden.json` is captured verbatim from the
 * real Python `fava.file.format_entries([create.<directive>(...)])` (the path
 * `server/app/api/entries.py::add_bulk_entries` uses to serialize each entry),
 * generated by feeding the same directive payloads through the in-repo
 * fava-slim + beancount venv. Each case asserts `entryInputToText` is
 * byte-identical to what Python emits for that single directive.
 */

const goldenText: Record<string, string> = golden;

/** One golden key → the structured input that must serialize to it. */
const cases: Array<{ name: string; input: LedgerEntryInput }> = [
  {
    name: "transaction_full",
    input: {
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        payee: "Employer",
        narration: "Salary",
        tags: ["income"],
        links: ["ref-1"],
        postings: [
          {
            units: { number: "3000.00", currency: "USD" },
            account: "Assets:Checking",
          },
          {
            units: { number: "-3000.00", currency: "USD" },
            account: "Income:Salary",
          },
        ],
      },
    },
  },
  {
    name: "transaction_narration_only",
    input: {
      type: "transaction",
      entry: {
        date: "2024-01-20",
        flag: "*",
        narration: "Groceries",
        postings: [
          {
            units: { number: "-50.00", currency: "USD" },
            account: "Assets:Checking",
          },
          {
            units: { number: "50.00", currency: "USD" },
            account: "Expenses:Food",
          },
        ],
      },
    },
  },
  {
    name: "transaction_payee_only_pending",
    input: {
      type: "transaction",
      entry: {
        date: "2024-02-01",
        flag: "!",
        payee: "Store",
        postings: [
          {
            units: { number: "-10.00", currency: "USD" },
            account: "Assets:Cash",
          },
          {
            units: { number: "10.00", currency: "USD" },
            account: "Expenses:Misc",
          },
        ],
      },
    },
  },
  {
    name: "transaction_price_flag_meta",
    input: {
      type: "transaction",
      entry: {
        date: "2024-03-01",
        flag: "*",
        narration: "FX trade",
        meta: { key1: "value1", num: "note" },
        postings: [
          {
            units: { number: "100.00", currency: "USD" },
            account: "Assets:USD",
            price: { number: "1.35", currency: "CAD" },
            flag: "!",
          },
          {
            units: { number: "-135.00", currency: "CAD" },
            account: "Assets:CAD",
          },
        ],
      },
    },
  },
  {
    name: "transaction_escaping",
    input: {
      type: "transaction",
      entry: {
        date: "2024-04-01",
        flag: "*",
        payee: 'Quote"Co',
        narration: "Line\\back",
        postings: [
          {
            units: { number: "-5.00", currency: "USD" },
            account: "Assets:Cash",
          },
          { units: { number: "5.00", currency: "USD" }, account: "Expenses:X" },
        ],
      },
    },
  },
  {
    name: "commodity",
    input: {
      type: "commodity",
      entry: { date: "2024-01-01", currency: "USD" },
    },
  },
  {
    name: "price",
    input: {
      type: "price",
      entry: {
        date: "2024-01-01",
        currency: "AAPL",
        amount: { number: "150.25", currency: "USD" },
      },
    },
  },
  {
    name: "note",
    input: {
      type: "note",
      entry: {
        date: "2024-01-01",
        content: "hello world",
        account: "Assets:Cash",
      },
    },
  },
  {
    name: "balance",
    input: {
      type: "balance",
      entry: {
        date: "2024-01-01",
        account: "Assets:Checking",
        amount: { number: "1000.00", currency: "USD" },
      },
    },
  },
  {
    name: "open_multi",
    input: {
      type: "open",
      entry: {
        date: "2024-01-01",
        account: "Assets:Checking",
        currencies: ["USD", "EUR"],
      },
    },
  },
  {
    name: "open_none",
    input: {
      type: "open",
      entry: { date: "2024-01-01", account: "Assets:Checking", currencies: [] },
    },
  },
  {
    name: "close",
    input: {
      type: "close",
      entry: { date: "2024-01-01", account: "Assets:Checking" },
    },
  },
  {
    name: "event",
    input: {
      type: "event",
      entry: {
        date: "2024-01-01",
        type: "location",
        description: "Paris, France",
      },
    },
  },
  {
    name: "document",
    input: {
      type: "document",
      entry: {
        date: "2024-01-01",
        account: "Assets:Cash",
        filename: "/path/to/doc.pdf",
      },
    },
  },
  {
    name: "document_tags_links",
    input: {
      type: "document",
      entry: {
        date: "2024-01-01",
        account: "Assets:Cash",
        filename: "/path/to/doc.pdf",
        tags: ["tagb", "taga"],
        links: ["link1"],
      },
    },
  },
  {
    name: "budget",
    input: {
      type: "budget",
      entry: {
        date: "2024-01-01",
        account: "Expenses:Food",
        interval: "monthly",
        amount: { number: "500.00", currency: "USD" },
      },
    },
  },
];

describe("entryInputToText — Fava-exact serialization parity", () => {
  it.each(cases)(
    "matches Python format_entries for $name",
    ({ name, input }) => {
      expect(goldenText[name]).toBeDefined();
      expect(entryInputToText(input)).toBe(goldenText[name]);
    },
  );

  it("covers every golden fixture", () => {
    const covered = new Set(cases.map((testCase) => testCase.name));
    const goldenKeys = Object.keys(goldenText);
    expect(goldenKeys.every((key) => covered.has(key))).toBe(true);
    expect(covered.size).toBe(goldenKeys.length);
  });

  // w23/106: omitted currencies render exactly like an explicit empty
  // list — a bare `open` line, byte-identical to the open_none golden.
  it("renders an omitted open currencies like an explicit empty list", () => {
    const omitted = entryInputToText({
      type: "open",
      entry: { date: "2024-01-01", account: "Assets:Checking" },
    });
    expect(omitted).toBe(goldenText["open_none"]);
    expect(omitted).toBe("2024-01-01 open Assets:Checking\n\n");
  });

  /**
   * A budget reaches this module as a `custom` directive, because that is the
   * only shape the bulk-entries contract defines for one — there is no
   * `budget` entry type on the wire (`EntryAddBulkEntriesRequest` in
   * `idl/beancount-ledger.openapi.json`). This module used to handle only the
   * in-process `budget` union, so every budget written through the API failed
   * with "Cannot read properties of undefined (reading 'type')".
   */
  it("renders a wire-shaped custom budget identically to the budget input", () => {
    const fromWire = entryInputToText({
      type: "custom",
      entry: {
        date: "2024-01-01",
        type: "budget",
        values: [
          { kind: "account", value: "Expenses:Food" },
          { kind: "text", value: "monthly" },
          { kind: "amount", number: "500.00", currency: "USD" },
        ],
      },
    });

    expect(fromWire).toBe(goldenText.budget);
  });

  it("maps every custom value kind onto its beancount rendering", () => {
    // `text` quotes, `account` does not, `number` is bare, `amount` pairs
    // number and currency — the four kinds the contract defines.
    const out = entryInputToText({
      type: "custom",
      entry: {
        date: "2024-03-04",
        type: "example",
        values: [
          { kind: "account", value: "Assets:Checking" },
          { kind: "text", value: "quoted" },
          { kind: "number", value: "12.50" },
          { kind: "amount", number: "3.00", currency: "EUR" },
        ],
      },
    });

    expect(out).toBe(
      '2024-03-04 custom "example" Assets:Checking "quoted" 12.50 3.00 EUR\n\n',
    );
  });

  // w23/033: the type and text values were quoted without escaping, so a
  // quote in either ended the string and the rest was written as source.
  it("escapes quotes and backslashes in a custom type and text value", () => {
    const out = entryInputToText({
      type: "custom",
      entry: {
        date: "2024-03-04",
        type: 'say "hi"',
        values: [{ kind: "text", value: 'a\\b"\n2024-03-04 open Assets:Evil' }],
      },
    });
    expect(out).toBe(
      '2024-03-04 custom "say \\"hi\\"" "a\\\\b\\"\n2024-03-04 open Assets:Evil"\n\n',
    );
  });

  // w23/053: the caller's meta values are strings; read as numbers or dates
  // they lost leading zeros and changed type.
  it("quotes every caller meta value, number- and date-shaped ones included", () => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2026-03-22",
        flag: "*",
        narration: "meta probe",
        postings: [
          { account: "Assets:Cash", units: { number: "-1", currency: "USD" } },
          { account: "Expenses:Food" },
        ],
        meta: {
          invoice: "00123",
          zip: "02134",
          ref: "1.50",
          due: "2026-01-31",
          neg: "-0",
        },
      },
    });
    for (const line of [
      '  invoice: "00123"',
      '  zip: "02134"',
      '  ref: "1.50"',
      '  due: "2026-01-31"',
      '  neg: "-0"',
    ])
      expect(out).toContain(line);
  });

  it("renders a custom directive that carries no values", () => {
    expect(
      entryInputToText({
        type: "custom",
        entry: { date: "2024-03-04", type: "marker" },
      }),
    ).toBe('2024-03-04 custom "marker"\n\n');
  });

  it("appends the trailing blank line that format_entries adds", () => {
    const out = entryInputToText({
      type: "close",
      entry: { date: "2024-01-01", account: "Assets:Checking" },
    });
    expect(out.endsWith("\n\n")).toBe(true);
  });

  it("round-trips tags/links sorted regardless of input order", () => {
    const out = entryInputToText({
      type: "document",
      entry: {
        date: "2024-01-01",
        account: "Assets:Cash",
        filename: "/path/to/doc.pdf",
        tags: ["zeta", "alpha"],
        links: ["mno"],
      },
    });
    expect(out).toContain("#alpha#zeta^mno");
  });

  it("expands scientific notation into ordinary decimals for WASM-safe source", () => {
    const transaction = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-09-08",
        flag: "*",
        narration: "Tiny",
        postings: [
          {
            units: { number: "1e-8", currency: "MUSD" },
            account: "Expenses:CostOfRevenue",
          },
          {
            units: { number: "-1e-8", currency: "MUSD" },
            account: "Assets:Current:Cash",
          },
        ],
      },
    });
    expect(transaction).toContain("0.00000001 MUSD");
    expect(transaction).toContain("-0.00000001 MUSD");
    expect(transaction).not.toMatch(/1e-8/i);

    const balance = entryInputToText({
      type: "balance",
      entry: {
        date: "2024-09-08",
        account: "Assets:Current:Cash",
        amount: { number: "1e-8", currency: "MUSD" },
      },
    });
    expect(balance).toContain("0.00000001 MUSD");
    expect(balance).not.toMatch(/1e-8/i);

    const price = entryInputToText({
      type: "price",
      entry: {
        date: "2024-09-08",
        currency: "BTC",
        amount: { number: "1e+21", currency: "USD" },
      },
    });
    expect(price).toContain("1000000000000000000000 USD");
    expect(price).not.toMatch(/1e\+?21/i);

    const custom = entryInputToText({
      type: "custom",
      entry: {
        date: "2024-09-08",
        type: "example",
        values: [
          { kind: "number", value: "1e-8" },
          { kind: "amount", number: "-1E-8", currency: "MUSD" },
        ],
      },
    });
    expect(custom).toBe(
      '2024-09-08 custom "example" 0.00000001 -0.00000001 MUSD\n\n',
    );

    const budget = entryInputToText({
      type: "budget",
      entry: {
        date: "2024-09-08",
        account: "Expenses:Food",
        interval: "monthly",
        amount: { number: "1e-8", currency: "USD" },
      },
    });
    expect(budget).toContain("0.00000001 USD");
  });

  // w23/043: the decimal check accepts `.5`, which Beancount cannot read.
  it.each([
    [".5", "0.5"],
    ["-.5", "-0.5"],
    ["+.50", "+0.50"],
    [".5e1", "5"],
    ["5.", "5."],
    ["+5", "+5"],
  ])("writes the amount %p as %p", (number, written) => {
    const out = entryInputToText({
      type: "balance",
      entry: {
        date: "2024-01-01",
        account: "Assets:Cash",
        amount: { number, currency: "USD" },
      },
    });
    expect(out).toContain(` ${written} USD`);
  });

  it("preserves ordinary decimal scale without rewriting through BigNumber", () => {
    const out = entryInputToText({
      type: "balance",
      entry: {
        date: "2024-09-08",
        account: "Assets:Checking",
        amount: { number: "1.2300", currency: "USD" },
      },
    });
    expect(out).toContain("1.2300 USD");
  });

  // w23/m6/t002: a typed cost renders as the lot beancount parses.
  it.each([
    [
      "dated and labelled",
      { number: "100", currency: "USD", date: "2024-01-15", label: "lot-a" },
      '{100 USD, 2024-01-15, "lot-a"}',
    ],
    ["dateless", { number: "100", currency: "USD" }, "{100 USD}"],
  ])("renders a %s cost", (_label, cost, rendered) => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        postings: [
          {
            units: { number: "10", currency: "HOOLI" },
            account: "Assets:Broker",
            cost,
          },
          {
            units: { number: "-1000", currency: "USD" },
            account: "Assets:Cash",
          },
        ],
      },
    });
    expect(out).toContain(`10 HOOLI ${rendered}`);
  });

  // w23/m6/t008: a cost label escapes like every other quoted string.
  it("escapes quotes and backslashes in a cost label", () => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        postings: [
          {
            units: { number: "10", currency: "HOOLI" },
            account: "Assets:Broker",
            cost: { number: "100", currency: "USD", label: 'a"b\\c' },
          },
          {
            units: { number: "-1000", currency: "USD" },
            account: "Assets:Cash",
          },
        ],
      },
    });
    expect(out).toContain('{100 USD, "a\\"b\\\\c"}');
  });

  // w23/m6/t003: posting tags/links sort onto the posting line like the header.
  it("renders posting tags and links sorted on the posting line", () => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        postings: [
          {
            units: { number: "10", currency: "USD" },
            account: "Expenses:Food",
            tags: ["zb", "ab"],
            links: ["l1"],
          },
          {
            units: { number: "-10", currency: "USD" },
            account: "Assets:Cash",
          },
        ],
      },
    });
    expect(out).toContain("10 USD #ab #zb ^l1");
  });

  // w23/m6/t003: posting metadata renders beneath its posting.
  it("renders posting metadata beneath the posting", () => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        postings: [
          {
            units: { number: "10", currency: "USD" },
            account: "Expenses:Food",
            meta: { receipt: "r-1" },
          },
          {
            units: { number: "-10", currency: "USD" },
            account: "Assets:Cash",
          },
        ],
      },
    });
    expect(out).toContain('receipt: "r-1"');
  });

  // w23/m6/t009: booking renders quoted on the open line, as beancount parses.
  it("renders booking on an open directive", () => {
    const out = entryInputToText({
      type: "open",
      entry: {
        date: "2024-01-15",
        account: "Assets:Broker",
        currencies: ["HOOLI"],
        booking: "FIFO",
      },
    });
    expect(out).toContain('open Assets:Broker');
    expect(out).toContain('"FIFO"');
  });

  // w23/m6/t009: tolerance renders number-first, the spelling beancount
  // parses (currency-first is a syntax error). The double space after `~`
  // is fava's align output, byte-verified against to_string above.
  it("renders tolerance on a balance directive", () => {
    const out = entryInputToText({
      type: "balance",
      entry: {
        date: "2024-01-15",
        account: "Assets:Cash",
        amount: { number: "100", currency: "USD" },
        tolerance: "0.01",
      },
    });
    expect(out).toContain("100 ~  0.01 USD");
  });

  // w23/m6/t010: a total price renders `@@`, never divided per unit.
  it("renders a total price on a posting", () => {
    const out = entryInputToText({
      type: "transaction",
      entry: {
        date: "2024-01-15",
        flag: "*",
        postings: [
          {
            units: { number: "10", currency: "HOOLI" },
            account: "Assets:Broker",
            totalPrice: { number: "1000", currency: "USD" },
          },
          {
            units: { number: "-1000", currency: "USD" },
            account: "Assets:Cash",
          },
        ],
      },
    });
    expect(out).toContain("10 HOOLI @@ 1000 USD");
  });

  // w23/m6/t010: pad renders the source account.
  it("renders a pad directive", () => {
    const out = entryInputToText({
      type: "pad",
      entry: {
        date: "2024-01-15",
        account: "Assets:Cash",
        sourceAccount: "Equity:Opening-Balances",
      },
    });
    expect(out).toContain("pad Assets:Cash Equity:Opening-Balances");
  });
});
